<?php
declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/csrf.php'; require_once __DIR__.'/connection.php'; require_alumni(); $email=$_SESSION['user_email'];$message='';$type='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$company=trim($_POST['company_name']??'');$job=trim($_POST['job_title']??'');$status=trim($_POST['employment_status']??'');$location=trim($_POST['work_location']??'');$start=trim($_POST['start_date']??'');$current=isset($_POST['is_current'])?1:0;if($company===''&&$job===''&&$status===''){$message='Add a company, position, or employment status.';$type='danger';}else{$stmt=mysqli_prepare($connection,'INSERT INTO employment_information(email,employment_status,company_name,job_title,work_location,start_date,is_current) VALUES(?,?,?,?,?,?,?)');if($stmt){mysqli_stmt_bind_param($stmt,'ssssssi',$email,$status,$company,$job,$location,$start,$current);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Employment record added.';$type='success';}}}
$jobs=[];$stmt=mysqli_prepare($connection,'SELECT * FROM employment_information WHERE email=? ORDER BY is_current DESC,start_date DESC,id DESC');if($stmt){mysqli_stmt_bind_param($stmt,'s',$email);mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($r))$jobs[]=$row;mysqli_stmt_close($stmt);} $pageTitle='Employment';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employment | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>Employment</h2><p>Build a clear timeline of your work experience.</p></div><?php if($message):?><div class="alert alert-<?=$type?>"><?=htmlspecialchars($message)?></div><?php endif;?><div class="panel"><form method="post"><?=csrf_field()?><div class="fields cols-2"><div class="field"><label>Status</label><input class="input" name="employment_status"></div><div class="field"><label>Employment type</label><input class="input" name="employment_type"></div><div class="field"><label>Company</label><input class="input" name="company_name"></div><div class="field"><label>Job title</label><input class="input" name="job_title"></div><div class="field"><label>Work location</label><input class="input" name="work_location"></div><div class="field"><label>Start date</label><input class="input" type="date" name="start_date"></div></div><label><input type="checkbox" name="is_current"> I currently work here</label><button class="btn btn-primary" name="save_job" type="submit">Save employment</button></form></div><div class="panel" style="margin-top:22px"><h2>Employment history</h2><?php foreach($jobs as $job):?><article class="record-card"><h3><?=htmlspecialchars($job['job_title']?:'Position not provided')?></h3><p><?=htmlspecialchars($job['company_name']?:'Company not provided')?> · <?=htmlspecialchars($job['work_location']?:'Location not provided')?></p><span class="tag"><?=htmlspecialchars($job['employment_status']?:'Status not provided')?></span></article><?php endforeach;if(!$jobs):?><p class="muted">No employment records yet.</p><?php endif;?></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
